// Pill Reminder App

class PillReminder {
    constructor() {
        this.pills = JSON.parse(localStorage.getItem('pills')) || [];
        this.history = JSON.parse(localStorage.getItem('pillHistory')) || {};
        this.currentFilter = 'all';
        this.today = this.getDateString(new Date());

        this.initializeElements();
        this.initializeEventListeners();
        this.initializeTodayTracking();
        this.render();
        this.startTimeChecker();
    }

    getDateString(date) {
        return date.toISOString().split('T')[0];
    }

    initializeElements() {
        this.form = document.getElementById('pillForm');
        this.pillList = document.getElementById('pillList');
        this.currentDateEl = document.getElementById('currentDate');
        this.totalPillsEl = document.getElementById('totalPills');
        this.takenPillsEl = document.getElementById('takenPills');
        this.missedPillsEl = document.getElementById('missedPills');
        this.pendingPillsEl = document.getElementById('pendingPills');
        this.progressBar = document.getElementById('progressBar');
        this.progressText = document.getElementById('progressText');
        this.historyChart = document.getElementById('historyChart');
        this.notification = document.getElementById('notification');
        this.notificationText = document.getElementById('notificationText');

        // Set current date
        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        this.currentDateEl.textContent = new Date().toLocaleDateString('en-US', options);
    }

    initializeEventListeners() {
        this.form.addEventListener('submit', (e) => {
            e.preventDefault();
            this.addPill();
        });

        document.querySelectorAll('.filter-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                this.currentFilter = btn.dataset.filter;
                this.renderPillList();
            });
        });
    }

    initializeTodayTracking() {
        if (!this.history[this.today]) {
            this.history[this.today] = {};
        }

        // Initialize tracking for each pill for today
        this.pills.forEach(pill => {
            if (!this.history[this.today][pill.id]) {
                this.history[this.today][pill.id] = 'pending';
            }
        });

        this.saveHistory();
    }

    addPill() {
        const name = document.getElementById('pillName').value.trim();
        const dosage = document.getElementById('pillDosage').value.trim();
        const time = document.getElementById('pillTime').value;
        const frequency = document.getElementById('pillFrequency').value;
        const notes = document.getElementById('pillNotes').value.trim();

        if (!name || !dosage || !time) return;

        const pill = {
            id: Date.now().toString(),
            name,
            dosage,
            time,
            frequency,
            notes,
            createdAt: new Date().toISOString()
        };

        this.pills.push(pill);
        this.savePills();

        // Initialize today's tracking for this pill
        if (!this.history[this.today]) {
            this.history[this.today] = {};
        }
        this.history[this.today][pill.id] = 'pending';
        this.saveHistory();

        this.form.reset();
        this.showNotification('Medication added successfully!', 'success');
        this.render();
    }

    deletePill(id) {
        this.pills = this.pills.filter(p => p.id !== id);
        this.savePills();

        // Remove from today's tracking
        if (this.history[this.today] && this.history[this.today][id]) {
            delete this.history[this.today][id];
            this.saveHistory();
        }

        this.showNotification('Medication removed.', 'warning');
        this.render();
    }

    markAsTaken(id) {
        if (!this.history[this.today]) {
            this.history[this.today] = {};
        }
        this.history[this.today][id] = 'taken';
        this.saveHistory();

        const pill = this.pills.find(p => p.id === id);
        this.showNotification(`${pill ? pill.name : 'Medication'} marked as taken! ✅`, 'success');
        this.render();
    }

    markAsMissed(id) {
        if (!this.history[this.today]) {
            this.history[this.today] = {};
        }
        this.history[this.today][id] = 'missed';
        this.saveHistory();

        const pill = this.pills.find(p => p.id === id);
        this.showNotification(`${pill ? pill.name : 'Medication'} marked as missed ❌`, 'error');
        this.render();
    }

    toggleStatus(id) {
        const currentStatus = this.history[this.today] ? this.history[this.today][id] : 'pending';
        if (currentStatus === 'taken') {
            this.history[this.today][id] = 'pending';
            this.saveHistory();
            this.render();
        } else {
            this.markAsTaken(id);
        }
    }

    getStatus(id) {
        if (this.history[this.today] && this.history[this.today][id]) {
            return this.history[this.today][id];
        }
        return 'pending';
    }

    formatTime(time24) {
        const [hours, minutes] = time24.split(':');
        const h = parseInt(hours);
        const ampm = h >= 12 ? 'PM' : 'AM';
        const h12 = h % 12 || 12;
        return `${h12}:${minutes} ${ampm}`;
    }

    formatFrequency(freq) {
        const map = {
            'daily': 'Daily',
            'twice': 'Twice Daily',
            'weekly': 'Weekly',
            'asNeeded': 'As Needed'
        };
        return map[freq] || freq;
    }

    render() {
        this.renderPillList();
        this.renderStats();
        this.renderHistory();
    }

    renderPillList() {
        const sortedPills = [...this.pills].sort((a, b) => a.time.localeCompare(b.time));

        let filteredPills = sortedPills;
        if (this.currentFilter !== 'all') {
            filteredPills = sortedPills.filter(pill => this.getStatus(pill.id) === this.currentFilter);
        }

        if (filteredPills.length === 0) {
            const messages = {
                'all': 'No medications scheduled. Add one above!',
                'pending': 'No pending medications. Great job!',
                'taken': 'No medications taken yet today.',
                'missed': 'No missed medications. Keep it up! 🎉'
            };
            this.pillList.innerHTML = `<p class="empty-message">${messages[this.currentFilter]}</p>`;
            return;
        }

        this.pillList.innerHTML = filteredPills.map(pill => {
            const status = this.getStatus(pill.id);
            const statusIcon = status === 'taken' ? '✓' : status === 'missed' ? '✕' : '';
            const notesHtml = pill.notes ? ` · ${pill.notes}` : '';

            return `
                <div class="pill-card ${status}">
                    <button class="pill-status-btn" onclick="app.toggleStatus('${pill.id}')" title="Toggle taken">
                        ${statusIcon}
                    </button>
                    <div class="pill-info">
                        <div class="pill-name">${this.escapeHtml(pill.name)}</div>
                        <div class="pill-details">${this.escapeHtml(pill.dosage)} · ${this.formatFrequency(pill.frequency)}${this.escapeHtml(notesHtml)}</div>
                    </div>
                    <div class="pill-time">${this.formatTime(pill.time)}</div>
                    <div class="pill-actions">
                        ${status === 'pending' ? `<button class="btn-miss" onclick="app.markAsMissed('${pill.id}')" title="Mark as missed">✕</button>` : ''}
                        <button class="btn-delete" onclick="app.deletePill('${pill.id}')" title="Delete">🗑</button>
                    </div>
                </div>
            `;
        }).join('');
    }

    renderStats() {
        const total = this.pills.length;
        let taken = 0;
        let missed = 0;
        let pending = 0;

        this.pills.forEach(pill => {
            const status = this.getStatus(pill.id);
            if (status === 'taken') taken++;
            else if (status === 'missed') missed++;
            else pending++;
        });

        this.totalPillsEl.textContent = total;
        this.takenPillsEl.textContent = taken;
        this.missedPillsEl.textContent = missed;
        this.pendingPillsEl.textContent = pending;

        const percentage = total > 0 ? Math.round((taken / total) * 100) : 0;
        this.progressBar.style.width = percentage + '%';
        this.progressText.textContent = `${percentage}% completed`;
    }

    renderHistory() {
        const days = [];
        const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

        for (let i = 6; i >= 0; i--) {
            const date = new Date();
            date.setDate(date.getDate() - i);
            const dateStr = this.getDateString(date);
            const dayName = dayNames[date.getDay()];

            let percentage = 0;
            if (this.history[dateStr]) {
                const dayData = this.history[dateStr];
                const ids = Object.keys(dayData);
                const total = ids.length;
                const taken = ids.filter(id => dayData[id] === 'taken').length;
                percentage = total > 0 ? Math.round((taken / total) * 100) : 0;
            }

            days.push({ dayName, percentage, isToday: i === 0 });
        }

        this.historyChart.innerHTML = days.map(day => `
            <div class="history-day">
                <div class="history-percent">${day.percentage}%</div>
                <div class="history-bar-container">
                    <div class="history-bar" style="height: ${Math.max(day.percentage, 3)}%"></div>
                </div>
                <div class="history-label" style="${day.isToday ? 'font-weight:700;color:#667eea' : ''}">
                    ${day.isToday ? 'Today' : day.dayName}
                </div>
            </div>
        `).join('');
    }

    showNotification(message, type = '') {
        this.notificationText.textContent = message;
        this.notification.className = `notification ${type}`;

        clearTimeout(this.notificationTimeout);
        this.notificationTimeout = setTimeout(() => {
            this.notification.classList.add('hidden');
        }, 3000);
    }

    startTimeChecker() {
        // Check every minute for upcoming pills
        setInterval(() => {
            const now = new Date();
            const currentTime = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

            this.pills.forEach(pill => {
                if (pill.time === currentTime && this.getStatus(pill.id) === 'pending') {
                    this.showNotification(`⏰ Time to take ${pill.name} (${pill.dosage})!`, 'warning');
                }
            });

            // Check if day changed
            const newToday = this.getDateString(new Date());
            if (newToday !== this.today) {
                this.today = newToday;
                this.initializeTodayTracking();
                this.render();
            }
        }, 60000);
    }

    escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    savePills() {
        localStorage.setItem('pills', JSON.stringify(this.pills));
    }

    saveHistory() {
        localStorage.setItem('pillHistory', JSON.stringify(this.history));
    }
}

// Initialize app
const app = new PillReminder();

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
    background: black;
    min-height: 100vh;
    padding: 20px;
}

.app-container {
    max-width: 600px;
    margin: 0 auto;
}

header {
    text-align: center;
    color: white;
    margin-bottom: 24px;
}

header h1 {
    font-size: 2rem;
    margin-bottom: 4px;
}

.date-display {
    font-size: 1rem;
    opacity: 0.9;
}

section {
    background: white;
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 20px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
}

section h2 {
    font-size: 1.2rem;
    color: #333;
    margin-bottom: 16px;
}

.form-group {
    margin-bottom: 14px;
}

.form-group label {
    display: block;
    font-size: 0.85rem;
    color: #666;
    margin-bottom: 4px;
    font-weight: 500;
}

.form-group input,
.form-group select {
    width: 100%;
    padding: 10px 14px;
    border: 2px solid #e0e0e0;
    border-radius: 10px;
    font-size: 1rem;
    transition: border-color 0.3s;
    outline: none;
}

.form-group input:focus,
.form-group select:focus {
    border-color: #667eea;
}

.btn-add {
    width: 100%;
    padding: 12px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 10px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
}

.btn-add:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
}

.btn-add:active {
    transform: translateY(0);
}

.filter-bar {
    display: flex;
    gap: 8px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}

.filter-btn {
    padding: 6px 16px;
    border: 2px solid #e0e0e0;
    border-radius: 20px;
    background: white;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s;
    font-weight: 500;
}

.filter-btn.active {
    background: #667eea;
    color: white;
    border-color: #667eea;
}

.filter-btn:hover:not(.active) {
    border-color: #667eea;
    color: #667eea;
}

.pill-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.empty-message {
    text-align: center;
    color: #999;
    padding: 20px;
    font-style: italic;
}

.pill-card {
    display: flex;
    align-items: center;
    padding: 14px;
    border-radius: 12px;
    border: 2px solid #f0f0f0;
    transition: all 0.3s;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateY(-10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.pill-card:hover {
    border-color: #667eea;
    box-shadow: 0 2px 10px rgba(102, 126, 234, 0.15);
}

.pill-card.taken {
    background: #f0fdf4;
    border-color: #86efac;
}

.pill-card.missed {
    background: #fef2f2;
    border-color: #fca5a5;
}

.pill-status-btn {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    border: 2px solid #d0d0d0;
    background: white;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    flex-shrink: 0;
    transition: all 0.2s;
}

.pill-status-btn:hover {
    border-color: #22c55e;
    background: #f0fdf4;
}

.pill-card.taken .pill-status-btn {
    background: #22c55e;
    border-color: #22c55e;
    color: white;
}

.pill-card.missed .pill-status-btn {
    background: #ef4444;
    border-color: #ef4444;
    color: white;
}

.pill-info {
    flex: 1;
    margin-left: 14px;
}

.pill-name {
    font-weight: 600;
    color: #333;
    font-size: 1rem;
}

.pill-details {
    font-size: 0.85rem;
    color: #888;
    margin-top: 2px;
}

.pill-time {
    font-size: 0.9rem;
    color: #667eea;
    font-weight: 600;
    margin-left: 8px;
    flex-shrink: 0;
}

.pill-actions {
    display: flex;
    gap: 6px;
    margin-left: 8px;
    flex-shrink: 0;
}

